"""Complete initial operational schema derived from Complete-Database-Schema.md."""

from __future__ import annotations

import sqlite3

UUID = "CHECK(length(id)=36)"
TS = "TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))"

STANDARD = """state TEXT NOT NULL DEFAULT 'active' CHECK(state IN ('active','inactive')),
 status_reason TEXT NOT NULL DEFAULT 'active',
 owner_user_id TEXT REFERENCES core_app_user(id) ON DELETE SET NULL,
 owner_team_id TEXT REFERENCES core_team(id) ON DELETE SET NULL,
 owning_business_unit_id TEXT REFERENCES core_business_unit(id) ON DELETE RESTRICT,
 created_on TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK(julianday(created_on) IS NOT NULL),
 created_by_id TEXT REFERENCES core_app_user(id) ON DELETE SET NULL,
 created_on_behalf_by_id TEXT REFERENCES core_app_user(id) ON DELETE SET NULL,
 modified_on TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK(julianday(modified_on) IS NOT NULL),
 modified_by_id TEXT REFERENCES core_app_user(id) ON DELETE SET NULL,
 modified_on_behalf_by_id TEXT REFERENCES core_app_user(id) ON DELETE SET NULL,
 row_version INTEGER NOT NULL DEFAULT 1 CHECK(row_version > 0),
 legacy_guid TEXT CHECK(legacy_guid IS NULL OR length(legacy_guid)=36)"""

